content.text:
        return end;
    }
}

static void run_train(ctx_t *c, uint32_t p0, uint32_t count, uint32_t width,
                      const uint8_t ranks[4], int reverse, uint32_t seed) {
    if (width == 0) return;
    uint64_t end_all = (uint64_t)p0 + count;
    for (uint64_t lo = p0; lo < end_all; lo += width) {
        uint64_t hi = lo + width;
        if (hi > end_all) hi = end_all;
        for (int i = 0; i < EPIC_STAR4_HOSTS; i++) {
            int rank = ranks[i];
            if (!is_required_source(c, rank)) continue;
            if (reverse) {
                for (uint64_t p = hi; p-- > lo;) {
                    fill_payload(c, seed, p, rank);
                    inject_data(c, rank, p, c->pbuf, NULL, 0);
                }
            } else {
                for (uint64_t p = lo; p < hi; p++) {
                    fill_payload(c, seed, p, rank);
                    inject_data(c, rank, p, c->pbuf, NULL, 0);
                }
            }
        }
        for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
            inject_ack(c, r, train_ack_prefix(c, r, hi));
        }
    }
}

int epic_case_run(void *context, const uint8_t *program, size_t length) {
    ctx_t *c = context;
    if (!c) return -1;
    reader_t r = { program, length, 0, 0 };
    while (r.off < r.len && !r.bad) {
        uint8_t op = rd_u8(&r);
        if (r.bad) break;
        switch (op) {
        case EV_DATA: {
            uint8_t rank = rd_u8(&r);
            uint32_t p = rd_u32le(&r);
            uint32_t count = rd_u32le(&r);
            int32_t step = (int32_t)rd_u32le(&r);
            uint32_t seed = rd_u32le(&r);
            uint32_t nvals = rd_u32le(&r);
            const uint8_t *vals = nvals ? rd_bytes(&r, (size_t)nvals * 4u) : NULL;
            uint32_t nxor = rd_u32le(&r);
            const uint8_t *xor = nxor ? rd_bytes(&r, (size_t)nxor * 5u) : NULL;
            if (r.bad || rank > 3) break;
            for (uint32_t i = 0; i < count; i++) {
                int64_t pi = (int64_t)p + (int64_t)i * (int64_t)step;
                uint64_t pm = (uint64_t)pi & MASK24;
                if (nvals) {
                    /* host-order words -> network order on the wire */
                    for (uint32_t j = 0; j < c->D; j++) {
                        uint32_t v = j < nvals ? rd32le(vals + 4u * j) : 0u;
                        c->pbuf[4u * j] = (uint8_t)(v >> 24);
                        c->pbuf[4u * j + 1u] = (uint8_t)(v >> 16);
                        c->pbuf[4u * j + 2u] = (uint8_t)(v >> 8);
                        c->pbuf[4u * j + 3u] = (uint8_t)v;
                    }
                } else {
                    fill_payload(c, seed, pm, rank);
                }
                inject_data(c, rank, pm, c->pbuf, xor, nxor);
            }
            break;
        }
        case EV_ACK: {
            uint8_t rank = rd_u8(&r);
            uint32_t upto = rd_u32le(&r);
            if (r.bad || rank > 3) break;
            inject_ack(c, rank, upto);
            break;
        }
        case EV_WIRE: {
            uint8_t rank = rd_u8(&r);
            uint32_t n = rd_u32le(&r);
            const uint8_t *bytes = rd_bytes(&r, n);
            if (r.bad || rank > 3) break;
            ingress(c, rank, bytes, n);
            break;
        }
        case EV_BUDGET: {
            int64_t n = rd_i64le(&r);
            if (r.bad) break;
            c->budget = n;
            break;
        }
